import{_ as e,o as t,c as n,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"飞书机器人接 Agent：一条消息的完整链路","description":"","frontmatter":{"title":"飞书机器人接 Agent：一条消息的完整链路"},"headers":[],"relativePath":"md/ai-agent/feishu-bot.md","filePath":"md/ai-agent/feishu-bot.md","lastUpdated":1795424423000}'),o={name:"md/ai-agent/feishu-bot.md"};function i(l,a,p,r,d,h){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="飞书机器人接-agent-一条消息的完整链路" tabindex="-1">飞书机器人接 Agent：一条消息的完整链路 <a class="header-anchor" href="#飞书机器人接-agent-一条消息的完整链路" aria-label="Permalink to &quot;飞书机器人接 Agent：一条消息的完整链路&quot;">​</a></h1><p>把一个 AI Agent 接到飞书，表面上只是&quot;收消息、发消息&quot;两件事，实际要做对一整套时序。</p><h2 id="链路全貌" tabindex="-1">链路全貌 <a class="header-anchor" href="#链路全貌" aria-label="Permalink to &quot;链路全貌&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户发消息</span></span>
<span class="line"><span>  → 飞书回调（HTTP POST 到你的事件地址）</span></span>
<span class="line"><span>  → 验签 + 解密 + 去重</span></span>
<span class="line"><span>  → 立刻返回 200（3 秒内，超时会重推）</span></span>
<span class="line"><span>  → 消息进队列</span></span>
<span class="line"><span>  → Agent 异步处理</span></span>
<span class="line"><span>  → 用 message_id 回复到原会话</span></span></code></pre></div><p>关键点：<strong>回调处理必须快速返回，真正的推理放到异步</strong>。飞书对回调有超时限制，超时后会重复推送同一条事件。很多人第一次接的时候在回调里同步跑模型，结果就是用户收到三条一模一样的回复。</p><h2 id="三个必须处理的问题" tabindex="-1">三个必须处理的问题 <a class="header-anchor" href="#三个必须处理的问题" aria-label="Permalink to &quot;三个必须处理的问题&quot;">​</a></h2><h3 id="_1-验签" tabindex="-1">1. 验签 <a class="header-anchor" href="#_1-验签" aria-label="Permalink to &quot;1. 验签&quot;">​</a></h3><p>飞书的回调带签名头，需要按官方给的算法用 <code>timestamp + nonce + 加密 key</code> 做校验。省掉这一步的直接后果是：任何知道 URL 的人都能伪造消息。</p><h3 id="_2-去重" tabindex="-1">2. 去重 <a class="header-anchor" href="#_2-去重" aria-label="Permalink to &quot;2. 去重&quot;">​</a></h3><p>请求超时重推、网络重试、用户重复发送，都会出现同一条消息进来两次。用飞书事件里的唯一标识做幂等键，落库或放 Redis，处理前先抢锁。没有这一步，Agent 会对着同一条指令反复执行——如果它调的是写操作，后果就不是多发几条消息了。</p><h3 id="_3-异步回复" tabindex="-1">3. 异步回复 <a class="header-anchor" href="#_3-异步回复" aria-label="Permalink to &quot;3. 异步回复&quot;">​</a></h3><p>回复要用原消息的 <code>message_id</code>（或者会话 id），而不是自己新建一个会话。注意区分这两种接口：</p><ul><li>回复单条消息：引用原消息，上下文落在群里</li><li>主动发消息到会话：需要 bot 有对应权限，且可能触发限流</li></ul><h2 id="长任务怎么反馈" tabindex="-1">长任务怎么反馈 <a class="header-anchor" href="#长任务怎么反馈" aria-label="Permalink to &quot;长任务怎么反馈&quot;">​</a></h2><p>Agent 处理超过十几秒时，用户会觉得&quot;它卡住了&quot;。这里有两个方案：</p><p><strong>方案一，先确认再推送。</strong> 收到消息立刻回一句&quot;收到，正在处理&quot;，处理完再发结果。用户的等待焦虑会明显下降。</p><p><strong>方案二，分步播报。</strong> 如果 Agent 是多步任务（查资料→写稿→发布），每一步完成后往会话里发一条进度。适合耗时几分钟的任务。</p><p>两种都要注意消息频率。飞书对单个 bot 的发送有速率限制，高频短消息很容易被限流，宁可合并成一条卡片消息。</p><h2 id="内网穿透的取舍" tabindex="-1">内网穿透的取舍 <a class="header-anchor" href="#内网穿透的取舍" aria-label="Permalink to &quot;内网穿透的取舍&quot;">​</a></h2><p>本地开发要接回调，就得把本地端口暴露出去。可选方向：</p><ul><li>反向代理 / 隧道服务（一次性 URL，方便但每次要换）</li><li>自己有服务器（域名 + HTTPS，稳定，但要维护证书和进程）</li><li>云函数做轻量转发（省运维，但调试不便）</li></ul><p>如果 Agent 本身要访问本地资源（文件、内网服务、桌面应用），纯云函数方案跑不通，还是得有一台常驻机器。这种时候用自己服务器 + 隧道兜底最实际。</p><h2 id="一个容易忽略的点" tabindex="-1">一个容易忽略的点 <a class="header-anchor" href="#一个容易忽略的点" aria-label="Permalink to &quot;一个容易忽略的点&quot;">​</a></h2><p>在群里 @ 机器人和私聊机器人，事件的字段结构不完全一样。私聊拿到的 <code>chat_id</code> 和群聊拿到的 <code>chat_id</code> 格式不同，如果代码里假设了&quot;一定是群&quot;或&quot;一定是单聊&quot;，就会在另一种场景下静默失败。先按两种都处理，再逐步收敛。</p><p>同理，消息里的 @ 提及、富文本、图片、文件，事件体结构都不同。一开始就写一个归一化层（把各种消息类型统一成 <code>{text, attachments}</code>），后面接 Agent 时省大量重复判断。</p>`,25)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
